import pandas as pd
import numpy as np

# Load all experiment CSVs
dfs = {}
for i in range(1, 6):
    try:
        dfs[i] = pd.read_csv(f"experiment_{i}_csv")
        print(f"\n=== Experiment {i} ===")
        print(f"Columns: {list(dfs[i].columns)}")
        print(f"Shape: {dfs[i].shape}")
        print(dfs[i].describe().round(2))
        if 'WaterClarityScore' in dfs[i].columns:
            print(f"\nCorrelations with WaterClarityScore:")
            print(dfs[i].corr(numeric_only=True)["WaterClarityScore"].round(3))
    except Exception as e:
        print(f"Experiment {i}: Error - {e}")

# Check for intervention columns
print("\n\n=== Intervention columns found ===")
for i, df in dfs.items():
    interv_cols = [c for c in df.columns if any(x in c.lower() for x in ['flush', 'chlor', 'metal', 'chel', 'dose', 'add', 'rate', 'flow', 'action', 'interv'])]
    if interv_cols:
        print(f"Exp {i}: {interv_cols}")
        for c in interv_cols:
            print(f"  {c}: {df[c].value_counts().head()}")
